test_that("Cheung S1 u S0 on the extreme and a mixed configuration", {
  for (levels in list(c(5, 5), c(3, 4), c(2, 3, 2))) {
    g <- DoseGrid(levels = levels)
    K <- n_combos(g)
    expect_equal(cheung_candidates(g, rep(0L, K)), K)
    expect_equal(cheung_candidates(g, rep(1L, K)), 1L)
  }
  # 5 x 5, U generated by (4, 5) and (5, 3): S1 = U except (5, 5), whose lower
  # covers are both in U; S0 = (3, 5), (4, 3), (4, 4), (5, 2).
  g <- DoseGrid(levels = c(5, 5))
  gamma <- matrix(0L, 5, 5)
  gamma[4, 5] <- gamma[5, 3:5] <- 1L
  expected <- combo_index(g, cbind(c(4, 5, 5, 3, 4, 4, 5), c(5, 3, 4, 5, 3, 4, 2)))
  expect_equal(sort(cheung_candidates(g, c(gamma))), sort(expected))
})

test_that("final sets are the maximal safe and minimal effective doses", {
  g <- DoseGrid(levels = c(3, 3))
  gamma <- c(matrix(c(0, 0, 1, 0, 1, 1, 1, 1, 1), 3, 3))
  expect_equal(pipe_final_set(g, gamma, "MTD"), combo_index(g, rbind(c(2, 1), c(1, 2))))
  expect_equal(pipe_final_set(g, gamma, "MED"), combo_index(g, rbind(c(3, 1), c(2, 2), c(1, 3))))
})

test_that("Riviere pick maximises P(pi near theta) over tried doses", {
  n <- c(6, 6, 0, 3)
  x <- c(0, 2, 0, 3)
  # dose 2 (2/6) is closest to theta = 0.3; dose 3 is untried
  expect_equal(riviere_pick(c(2, 3), 0.3, 0.5, 0.5, n, x), 2L)
  expect_equal(riviere_pick(c(1, 4), 0.3, 0.5, 0.5, n, x), 1L)
  expect_equal(riviere_pick(c(1, 4), 0.3, 0.5, 0.5, n, x, within_set = FALSE), 2L)
  expect_true(is.na(riviere_pick(3, 0.3, 0.5, 0.5, n, x)))
})

test_that("constraints: start dose, neighbourhood and one level above given doses", {
  g <- DoseGrid(levels = c(4, 4))
  expect_equal(ms_constraint(g, integer()), 1L)
  expect_equal(ms_constraint(g, integer(), start = 6L), 6L)
  last <- combo_index(g, c(2, 2))
  expect_equal(sort(ms_constraint(g, c(1L, last))),
               sort(combo_index(g, as.matrix(expand.grid(1:3, 1:3)))))
  # given (1, 1) and (3, 1): allowed = levels <= (2, 2) or <= (4, 2)
  hist <- combo_index(g, rbind(c(1, 1), c(3, 1)))
  expect_equal(sort(ms_constraint(g, hist, "non-neighbouring")),
               sort(combo_index(g, as.matrix(expand.grid(1:4, 1:2)))))
})

test_that("closest rule treats inadmissible doses as neither", {
  g <- DoseGrid(levels = c(3, 3))
  gamma <- c(matrix(c(0, 0, 1, 0, 1, 1, 1, 1, 1), 3, 3))
  all_in <- rep(TRUE, 9)
  # safe doses (2,1), (1,2) and toxic doses (3,1), (2,2), (1,3)
  expect_equal(ms_closest(g, gamma, all_in),
               sort(combo_index(g, rbind(c(2, 1), c(1, 2), c(3, 1), c(2, 2), c(1, 3)))))
  # all safe: over the grid only (3, 3) is dominant, within the neighbourhood
  # of (1, 1) it is (2, 2), the diagonal step
  A <- seq_len(9) %in% ms_constraint(g, 1L)
  expect_equal(ms_closest(g, rep(0L, 9), all_in), 9L)
  expect_equal(ms_closest(g, rep(0L, 9), A), combo_index(g, c(2, 2)))
})

# The 2D matrix version of the adjacent rule from gPIPE 0.1.0
# (calculateAdjacentDoses), kept here as a reference.
adjacent_2d <- function(vec, nrows, ncols) {
  mat <- matrix(vec, nrow = nrows, ncol = ncols)
  up <- mat == 1 & (rbind(0, mat[-nrows, ]) == 0 | cbind(0, mat[, -ncols]) == 0 |
                      rbind(0, cbind(0, mat[, -ncols])[-nrows, ]) == 0)
  low <- mat == 0 & (rbind(mat[-1, ], 1) == 1 | cbind(mat[, -1], 1) == 1 |
                       rbind(cbind(mat[, -1], 1)[-1, ], 1) == 1)
  up | low
}

test_that("adjacent rule matches the 2D matrix version", {
  set.seed(4)
  g <- DoseGrid(levels = c(4, 5))
  C <- ref_upsets(c(4, 5))
  for (r in sample(nrow(C), 30)) {
    old <- which(c(adjacent_2d(C[r, ], 4, 5)))
    expect_equal(ms_adjacent(g, C[r, ]), old)
  }
})

test_that("selection weights, with ties in S up to rounding", {
  S <- c(1 / 16 + 2, (1 / 16 + 2) * (1 + 1e-15), 3, 4)
  expect_equal(ms_selection_weights(1:3, S, "min_S"), c(0.5, 0.5, 0, 0))
  expect_equal(ms_selection_weights(c(1, 3), S, "inverse_S"),
               c(1 / S[1], 0, 1 / S[3], 0) / (1 / S[1] + 1 / S[3]))
  expect_equal(ms_selection_weights(c(2, 4), S, "equal"), c(0, 0.5, 0, 0.5))
  expect_equal(sum(ms_selection_weights(1:4, S, "inverse_sqrt_S")), 1)
})

test_that("M&S stops when no dose in the neighbourhood is safe", {
  g <- DoseGrid(levels = c(3, 3))
  # last dose (3, 3); every dose likely toxic except d11
  p <- rep(0.99, 9)
  p[1] <- 0.01
  n <- rep(3, 9)
  out <- ms_decide(g, p, n, S = n + 1, history = c(1L, 5L, 9L), final = TRUE)
  expect_true(1L %in% out$safe)
  expect_true(out$stopped)
  expect_equal(out$rp2d, integer())
  expect_null(out$candidates)
})

test_that("M&S decision without the safety rule uses the estimate only", {
  g <- DoseGrid(levels = c(3, 3))
  p <- c(0.1, 0.2, 0.7, 0.2, 0.6, 0.8, 0.7, 0.8, 0.9)
  n <- c(3, 3, 0, 3, 0, 0, 0, 0, 0)
  out <- ms_decide(g, p, n, S = n + 1, history = c(1L, 2L), safety = NULL, final = TRUE)
  expect_null(out$q)
  expect_equal(out$mode, pipe_estimate(g, stats::qlogis(p), "MTD"))
  expect_true(all(out$candidates %in% out$neighbourhood))
  expect_equal(sum(out$prob), 1)
  expect_true(all(n[out$rp2d] > 0 & out$mode[out$rp2d] == 0))
})

test_that("M&S decision with the safety rule works for three drugs", {
  g <- DoseGrid(levels = c(3, 3, 3))
  set.seed(31)
  n <- sample(0:4, 27, replace = TRUE)
  x <- stats::rbinom(27, n, stats::plogis(-2 + 0.7 * rowSums(g@combos - 1)))
  p <- beta_exceedance(0.3, 0.3, 0.7, n, x)
  out <- ms_decide(g, p, n, S = n + 1, history = c(1L, 2L, 5L))
  # brute force over the 980 up-sets
  C <- ref_upsets(c(3, 3, 3))
  w <- exp(drop(C %*% stats::qlogis(p)))
  expect_equal(out$q, drop(crossprod(C, w / sum(w))), tolerance = 1e-12)
  expect_equal(out$mode, ref_solve(c(3, 3, 3), ref_gain(p), largest = TRUE))
  expect_equal(out$safe, which(out$q < 0.8))
  expect_true(all(out$candidates %in% out$admissible))
})

test_that("M&S decisions keep their set relations under every option", {
  keep <- array(TRUE, c(3, 3, 2))
  keep[2, 2, 1] <- FALSE
  grids <- list(DoseGrid(levels = c(4, 4)), DoseGrid(levels = c(3, 3, 3)),
                DoseGrid(levels = c(3, 3, 2), keep = keep))
  set.seed(25)
  for (g in grids) {
    K <- n_combos(g)
    C <- oracle_upsets(g)
    for (rep in 1:5) {
      n <- sample(0:4, K, replace = TRUE)
      x <- stats::rbinom(K, n, stats::plogis(-2.5 + 0.6 * rowSums(g@combos - 1)))
      p <- beta_exceedance(0.3, 0.3, 0.7, n, x)
      history <- c(1L, sample(K, 2))
      w <- exp(drop(C %*% stats::qlogis(p)))
      q_ref <- drop(crossprod(C, w / sum(w)))
      for (admis in c("closest", "adjacent")) {
        for (constraint in c("neighbouring", "non-neighbouring")) {
          out <- ms_decide(g, p, n, S = n + 1, history = history, admis = admis,
                           constraint = constraint, final = TRUE)
          info <- paste(paste(g@levels, collapse = "x"), admis, constraint, rep)
          expect_equal(out$q, q_ref, tolerance = 1e-12, info = info)
          expect_true(is_upset(g, out$mode), info = info)
          expect_equal(out$safe, which(q_ref < 0.8), info = info)
          expect_equal(out$admissible, intersect(out$neighbourhood, out$safe), info = info)
          expect_equal(out$stopped, !length(out$admissible), info = info)
          if (out$stopped) {
            expect_equal(out$rp2d, integer(), info = info)
          } else {
            expect_true(length(out$candidates) > 0, info = info)
            expect_true(all(out$candidates %in% out$admissible), info = info)
            expect_equal(sum(out$prob), 1, info = info)
            expect_true(all(which(out$prob > 0) %in% out$candidates), info = info)
            expect_true(all(out$mode[out$rp2d] == 0 & n[out$rp2d] > 0 &
                              out$rp2d %in% out$safe), info = info)
          }
        }
      }
    }
  }
})

test_that("ms_decide checks its inputs", {
  g <- DoseGrid(levels = c(2, 2))
  p <- c(0.1, 0.3, 0.4, 0.8)
  n <- rep(1, 4)
  expect_error(ms_decide(g, p[-1], n, S = n + 1, history = 1L), "one entry per combination")
  expect_error(ms_decide(g, p, n, S = n[-1], history = 1L), "one entry per combination")
  expect_error(ms_decide(g, c(NA, p[-1]), n, S = n + 1, history = 1L), "missing")
  expect_error(ms_decide(g, p, n, S = n + 1, history = c(1L, 5L)), "combination indices")
})
